insert into mach_customs (machine_key, dt, importer, inn, exporter, origin, incoterms, place, hs10, pn, descr, usd_kg, src) values
  ('R1700G', '2024-03-05', 'ООО "ТЕХСТАР"', '7839046552', 'MILEQUIP CORPORATION', 'CN', 'EXW', 'SHENYANG', '8412904008', 'R1700G', 'ЧАСТЬ ГИДРОЦИЛИНДРА: МЕТАЛЛИЧЕСКАЯ ВТУЛКА ГИДРОЦИЛИНДРА ПОГРУЗОЧНО-ДОСТАВОЧНОЙ МАШИНЫ CАTERPILLАR R1700G, ПОСТАВЛЯЕТСЯ ДЛЯ СОБСТВЕННЫХ НУЖД, НЕ ПОДЛЕЖИТ ОТЧУЖДЕНИЮ ТРЕТЬИМ ЛИЦАМ.. .', '39.02', 'выгрузка ГлобусВЭД (zip/customs/out)'),
